// Package: Microsoft.Extensions.AI
// Install: dotnet add package Microsoft.Extensions.AI.OpenAI --version 9.*

using Microsoft.Extensions.AI;
using OpenAI;

public sealed class PromptComposer
{
    private readonly IChatClient _chatClient;

    public PromptComposer(IChatClient chatClient)
    {
        _chatClient = chatClient;
    }

    public async Task<string> GenerateAnswerAsync(
        string userQuestion,
        string retrievedContext,
        CancellationToken cancellationToken = default)
    {
        var messages = new List<ChatMessage>
        {
            new SystemMessage("You are a helpful assistant. Answer ONLY using the provided context. "
                            + "If the answer is not in the context, say 'I don't know.'"),
            new UserMessage($"Context:\n{retrievedContext}\n\nQuestion: {userQuestion}")
        };

        ChatResponse response = await _chatClient.GetResponseAsync(
            messages,
            cancellationToken: cancellationToken);

        return response.Text;
    }
}

// Usage example
var composer = new PromptComposer(new OpenAIClient(apiKey).AsChatClient("gpt-4o-mini"));

string answer = await composer.GenerateAnswerAsync(
    userQuestion: "What is RAG?",
    retrievedContext: "RAG stands for Retrieval-Augmented Generation. "
                    + "It augments LLM prompts with retrieved context at query time.");

Console.WriteLine(answer);
// Expected output: RAG stands for Retrieval-Augmented Generation...
